export const BODY: string = "\n<p>چمک، ایکسپوزر، اور کنٹراسٹ وہ تین کنٹرول ہیں جو ہر فوٹو ایڈیٹر دیتا ہے، اور انہیں الجھانا آسان ہے۔ تینوں تصویر کو ہلکا یا گہرا کرتے ہیں، مگر وہ مختلف طریقے سے کرتے ہیں۔</p>\n<p>غلط والا استعمال کرنے سے بدتر نتیجہ ملتا ہے۔ جس تصویر کو کنٹراسٹ چاہیے وہ صرف روشن کرنے پر دھلی ہوئی لگے گی، اور جس تصویر کو چمک چاہیے وہ صرف کنٹراسٹ بڑھانے پر سخت لگے گی۔</p>\n<p>اس مضمون میں ہر کنٹرول بتایا گیا ہے، وہ کیسے مختلف ہیں، وہ کیسے ملتے ہیں، اور ہر صورت میں کسے استعمال کریں۔ یہ ہر دوسری فوٹو ایڈیٹنگ کی بنیاد ہے۔</p>\n<h2 id=\"what-each-does\">ہر کنٹرول کیا کرتا ہے</h2>\n<p>چمک ہر پکسل کو سفید یا سیاہ کی طرف یکساں منتقل کرتی ہے، پوری تصویر میں برابر۔ یہ سب سے سادہ کنٹرول ہے، اور مجموعی طور پر تاریک یا روشن تصویر کو ٹھیک کرتا ہے۔</p>\n<p>ایکسپوزر بدلتا ہے کہ تصویر نے کتنی روشنی پکڑی ہوئی لگتی ہے۔ یہ جھلکیوں اور سایوں کو مختلف متاثر کرتا ہے، اور انتہاؤں پر زیادہ تفصیل محفوظ رکھتا ہے۔</p>\n<p>کنٹراسٹ تصویر کے سب سے تاریک اور سب سے روشن حصوں کے درمیان فاصلہ پھیلاتا یا سکیڑتا ہے۔ اسے بڑھانے سے تاریک گہرے اور روشن ہلکے ہوتے ہیں، جبکہ کم کرنے سے تصویر نرم ہو جاتی ہے۔</p>\n<p>اس طرح سوچیں: چمک پوری ٹونل حد کو منتقل کرتی ہے، ایکسپوزر اسے نئی شکل دیتا ہے، اور کنٹراسٹ اسے پھیلاتا ہے۔ ہر ایک مختلف مسئلہ حل کرتا ہے۔</p>\n<h2 id=\"brightness-explained\">چمک، سادہ الفاظ میں</h2>\n<p>چمک یکساں تبدیلی ہے۔ ہر پکسل ایک ہی مقدار سے ہلکا یا گہرا ہوتا ہے، اس لیے اشیاء کے درمیان نسبتی فرق ایک جیسا رہتا ہے۔</p>\n<p>یہ مجموعی طور پر بہت تاریک یا بہت روشن تصویر کے لیے تیز ترین حل ہے۔ 15 فیصد روشن کی گئی تاریک اندرونی تصویر نظر آنے لگتی ہے، اور تبدیلی پیش گوئی کے قابل ہوتی ہے۔</p>\n<p>چمک کی کمزوری انتہائیں ہیں۔ اسے بہت زیادہ دھکیلنے سے جھلکیاں دھل جاتی ہیں اور روشن علاقے بے خصوصیت سفید بن جاتے ہیں، کیونکہ سب کچھ ایک ساتھ حرکت کرتا ہے۔</p>\n<p>چمک تب استعمال کریں جب پوری تصویر کو اوپر یا نیچے جانا ہو۔ یہ مجموعی ایکسپوزر مسئلے کے لیے درست اوزار ہے، اور اس تصویر کے لیے غلط اوزار ہے جو صرف ایک حصے میں تاریک ہو۔</p>\n<h2 id=\"exposure-explained\">ایکسپوزر، سادہ الفاظ میں</h2>\n<p>ایکسپوزر اسی نام کی کیمرہ سیٹنگ کی نقل کرتا ہے۔ کیمرے میں ایکسپوزر وہ روشنی ہوتی ہے جو سینسر پر پڑتی ہے، اور ایڈیٹر میں یہ اس مقدار کو بدلنے کی نقل کرتا ہے۔</p>\n<p>چمک کے برعکس، ایکسپوزر ٹونل حد کو غیر یکساں برتتا ہے۔ اس کا درمیانی ٹون پر مضبوط اثر ہوتا ہے اور انتہائی جھلکیوں اور سایوں پر نرم اثر ہوتا ہے۔</p>\n<p>اس سے ایکسپوزر بہتر انتخاب بنتا ہے جب جھلکیاں اہمیت رکھتی ہوں۔ روشن آسمان ایکسپوزر تبدیلی کے تحت اپنی شکل رکھتا ہے، جبکہ چمک تبدیلی اسے دھو سکتی ہے۔</p>\n<p>بہت سے براؤزر ایڈیٹر ایکسپوزر کے بجائے چمک دیتے ہیں، کیونکہ اسے نافذ کرنا سادہ ہوتا ہے۔ جب صرف چمک دستیاب ہو تو چھوٹے قدم استعمال کریں اور جھلکیاں چیک کریں۔</p>\n<h2 id=\"contrast-explained\">کنٹراسٹ، سادہ الفاظ میں</h2>\n<p>کنٹراسٹ فرق کے بارے میں ہے۔ زیادہ کنٹراسٹ والی تصویر میں گہرے سیاہ اور روشن سفید ہوتے ہیں جن کے درمیان مضبوط خلا ہوتا ہے، جبکہ کم کنٹراسٹ والی تصویر میں سب کچھ درمیان میں ہوتا ہے۔</p>\n<p>کنٹراسٹ بڑھانے سے تاریک گہرے اور روشن ہلکے ہوتے ہیں۔ یہ چپٹی تصویر میں جان اور گہرائی بڑھاتا ہے، مگر یہ سایوں کو سیاہ میں کچل بھی سکتا ہے اور جھلکیوں کو کاٹ بھی سکتا ہے۔</p>\n<p>کنٹراسٹ کم کرنے سے الٹ ہوتا ہے۔ یہ تصویر کو نرم کرتا ہے، تاریک اور روشن کو قریب لاتا ہے، جو دھندلی تصاویر اور نرم پورٹریٹ کے لیے موزوں ہوتا ہے۔</p>\n<p>کنٹراسٹ تب استعمال کریں جب تصویر چپٹی اور سرمئی لگے، حالانکہ اس کی مجموعی چمک درست ہو۔ مسئلہ سطح نہیں بلکہ پھیلاؤ ہے۔</p>\n<h2 id=\"how-they-interact\">تینوں کنٹرول کیسے ملتے ہیں</h2>\n<p>چمک اور کنٹراسٹ سیدھا ملتے ہیں۔ تصویر روشن کرنے سے وہ اکثر چپٹی لگتی ہے، کیونکہ سایوں کو اٹھانے سے تاریک اور روشن کے درمیان خلا کم ہو جاتا ہے۔</p>\n<p>ایکسپوزر اور کنٹراسٹ بھی ملتے ہیں۔ ایکسپوزر بڑھانے سے جھلکیاں دھل سکتی ہیں، جبکہ کنٹراسٹ بڑھانے سے وہ گہرائی واپس آتی ہے جو ایکسپوزر تبدیلی نے ہٹائی تھی۔</p>\n<p>عام پیٹرن یہ ہے کہ پہلے چمک، پھر کنٹراسٹ ایڈجسٹ کریں۔ چمک مجموعی سطح طے کرتی ہے، اور کنٹراسٹ اس سطح کے ارد گرد پھیلاؤ کو بہتر کرتا ہے۔</p>\n<p>ایک کنٹرول بدلنے سے دوسروں کی ضرورت بدل جاتی ہے۔ بڑی چمک حرکت کے بعد کنٹراسٹ دوبارہ چیک کریں، اور بڑی کنٹراسٹ حرکت کے بعد چمک دوبارہ چیک کریں۔</p>\n<h2 id=\"when-to-use-brightness\">چمک کب استعمال کریں</h2>\n<p>چمک تب استعمال کریں جب پوری تصویر بہت تاریک یا بہت روشن ہو۔ تاریک اندرونی تصویر، مدھم ابر آلود لینڈ اسکیپ، یا دھندلا اسکین سب کو مجموعی اٹھاؤ چاہیے ہوتا ہے۔</p>\n<p>چمک اسکرین شاٹس اور دستاویزات کے لیے بھی درست انتخاب ہے۔ متن پڑھنے کے قابل ہونا چاہیے، اور یکساں اٹھاؤ تاریک اسکین کو اس کی خصوصیت بدلے بغیر صاف کرتا ہے۔</p>\n<p>جس تصویر کے پیچھے متن بیٹھے گا اس کے لیے چمک وہ اوزار ہے جس سے اسے گہرا کریں۔ گہری تصویر سفید متن کو پڑھنے کے قابل بناتی ہے، جو سلائیڈ اور پوسٹر کے لیے موزوں ہے۔</p>\n<p>چمک سے بچیں جب تصویر کا صرف حصہ غلط ہو۔ روشن آسمان والا تاریک سامنے والا حصہ مختلف طریقہ چاہتا ہے، کیونکہ چمک دونوں حصوں کو ساتھ حرکت دیتی ہے۔</p>\n<h2 id=\"when-to-use-exposure\">ایکسپوزر کب استعمال کریں</h2>\n<p>ایکسپوزر تب استعمال کریں جب جھلکیاں اہمیت رکھتی ہوں۔ تفصیل والے آسمان والا لینڈ اسکیپ، روشن جلد جھلکیوں والا پورٹریٹ، یا چمکدار سطحوں والی پروڈکٹ فوٹو سب کو یہ چاہیے ہوتا ہے۔</p>\n<p>ایکسپوزر اس تصویر کے لیے بہتر انتخاب ہے جو کچھ غلط ہو۔ چھوٹی ایکسپوزر تبدیلی سطح کو درست کرتی ہے بغیر اس سخت دھلائی کے جو بڑی چمک حرکت دیتی ہے۔</p>\n<p>جب آپ کا ایڈیٹر صرف چمک دے تو چھوٹے چمک قدم استعمال کر کے اور ہر ایک کے بعد جھلکیاں چیک کر کے ایکسپوزر کی نقل کریں۔ نتیجہ کافی قریب ہوتا ہے۔</p>\n<p>مضبوط دھوپ میں لی گئی تصویر کے لیے ایکسپوزر محفوظ کنٹرول ہے۔ یہ روشن علاقوں کو محفوظ رکھتے ہوئے سایوں کو اٹھاتا ہے، جو چمک نہیں کر سکتی۔</p>\n<h2 id=\"when-to-use-contrast\">کنٹراسٹ کب استعمال کریں</h2>\n<p>کنٹراسٹ تب استعمال کریں جب تصویر چپٹی اور سرمئی لگے، حالانکہ اس کی مجموعی چمک درست ہو۔ مسئلہ پھیلاؤ ہے، سطح نہیں، اور صرف کنٹراسٹ اسے ٹھیک کرتا ہے۔</p>\n<p>کنٹراسٹ دھندلی تصاویر، دھند والے لینڈ اسکیپ، اور مدھم اندرونی شاٹس کے لیے درست انتخاب ہے۔ چھوٹا اضافہ جان بڑھاتا ہے اور تصویر کو دوبارہ ٹھوس محسوس کراتا ہے۔</p>\n<p>سخت تصویر کو نرم کرنے کے لیے منفی کنٹراسٹ استعمال کریں۔ مضبوط سایوں والے دوپہر کے پورٹریٹ نرم پھیلاؤ سے فائدہ اٹھاتے ہیں، جو سخت کناروں کو چپٹا کرتا ہے۔</p>\n<p>اہم سایہ یا جھلکی تفصیل والی تصاویر پر بڑی کنٹراسٹ حرکت سے بچیں۔ انتہائیں پہلے کٹتی ہیں، اور کٹا ہوا آسمان یا کچلا ہوا سایہ بحال نہیں ہو سکتا۔</p>\n<h2 id=\"order-of-edits\">درست ترتیب: پہلے چمک، پھر کنٹراسٹ</h2>\n<p>چمک سے شروع کریں، کیونکہ یہ مجموعی سطح طے کرتی ہے۔ بہت تاریک تصویر کو اس کے کنٹراسٹ کا فیصلہ کرنے سے پہلے اٹھانا چاہیے، اور بہت روشن تصویر کو پہلے گہرا کرنا چاہیے۔</p>\n<p>اگلا، کنٹراسٹ ایڈجسٹ کریں۔ سطح طے ہونے پر آپ دیکھ سکتے ہیں کہ تصویر چپٹی ہے یا جان دار، اور چھوٹی کنٹراسٹ حرکت پھیلاؤ کو ٹھیک کرتی ہے۔</p>\n<p>آخر میں، چمک دوبارہ چیک کریں۔ کنٹراسٹ تبدیلی تصویر کو گہرا یا ہلکا محسوس کرا سکتی ہے، اس لیے کنٹراسٹ کے بعد چھوٹی چمک تبدیلی اکثر بہتری لاتی ہے۔</p>\n<p>ہر مرحلے پر چھوٹے قدم میں کام کریں۔ 10 فیصد چمک حرکت اور 10 فیصد کنٹراسٹ حرکت کو کنٹرول کرنا کسی ایک کی 30 فیصد حرکت سے آسان ہوتا ہے۔</p>\n<h2 id=\"portraits\">پورٹریٹ: کون سا کنٹرول سب سے اہمیت رکھتا ہے</h2>\n<p>پورٹریٹ کو نرم چمک اور احتیاط والا کنٹراسٹ چاہیے ہوتا ہے۔ بہت تاریک چہرہ اظہار چھپاتا ہے، مگر بہت زیادہ کنٹراسٹ والا چہرہ سخت اور بوڑھا لگتا ہے۔</p>\n<p>10 سے 15 فیصد چھوٹی چمک اٹھاؤ سے شروع کریں۔ جلد کے رنگ چیک کریں: وہ قدرتی طور پر روشن لگنے چاہیے، ایسا نہیں جیسے قریب سے فلیش چلا ہو۔</p>\n<p>کنٹراسٹ صرف تب شامل کریں جب پورٹریٹ چپٹا لگے۔ 10 فیصد کا چھوٹا اضافہ اکثر کافی ہوتا ہے، اور بڑی حرکتیں جلد کو کھردرا بنا سکتی ہیں۔</p>\n<p>روشن کھڑکی کے سامنے لیے گئے پورٹریٹ کے لیے کوئی ایک کنٹرول چہرہ اور پس منظر دونوں کو ٹھیک نہیں کرتا۔ نرمی سے روشن کریں اور سمجھوتا قبول کریں، یا تصویر دوبارہ لیں۔</p>\n<h2 id=\"landscapes\">لینڈ اسکیپ: آسمان اور سامنے والے حصے کو متوازن کرنا</h2>\n<p>لینڈ اسکیپ کو اکثر سامنے والے حصے کے لیے چمک اور آسمان کے لیے تحمل چاہیے ہوتا ہے۔ یکساں چمک بڑھانا زمین کو ٹھیک کرتے ہوئے بادلوں کو دھو سکتا ہے۔</p>\n<p>درمیانی چمک بڑھاؤ استعمال کریں اور پہلے آسمان چیک کریں۔ اگر بادل اپنی شکل کھو دیں تو آپ بہت آگے جا چکے ہیں، اور چھوٹی حرکت درست جواب ہے۔</p>\n<p>کنٹراسٹ شامل کریں تاکہ وہ گہرائی واپس آئے جو روشن کرنے سے ہٹی تھی۔ صاف آسمان اور تفصیل والے سامنے والے حصے والے لینڈ اسکیپ کو دونوں کنٹرول ساتھ کام کرتے ہوئے چاہیے ہوتے ہیں۔</p>\n<p>صبح اور شام کے لینڈ اسکیپ اس جوڑے سے سب سے زیادہ فائدہ اٹھاتے ہیں۔ کم روشنی امیر رنگ دیتی ہے، اور چھوٹی چمک اٹھاؤ اور چھوٹا کنٹراسٹ اضافہ انہیں نکال لاتا ہے۔</p>\n<h2 id=\"screenshots\">اسکرین شاٹس اور دستاویزات: پہلے چمک</h2>\n<p>اسکرین شاٹس اور اسکین شدہ دستاویزات کو کنٹراسٹ سے زیادہ چمک چاہیے ہوتی ہے۔ مقصد صاف پس منظر پر پڑھنے کے قابل متن ہے، اور یکساں اٹھاؤ اسے سیدھا حاصل کرتا ہے۔</p>\n<p>چمک بڑھائیں جب تک متن صاف اور پس منظر سفید نہ ہو جائے۔ صاف سفید پس منظر اور گہرے متن والی دستاویز پڑھنے اور پرنٹ کرنے میں آسان ہوتی ہے۔</p>\n<p>کنٹراسٹ صرف تب شامل کریں جب روشن کرنے کے بعد بھی متن سرمئی لگے۔ چھوٹا اضافہ حروف کو گہرا کرتا ہے اور کناروں کو تیز کرتا ہے، جو چھوٹے متن کو سب سے زیادہ مدد دیتا ہے۔</p>\n<p>اسکرین شاٹس کو PNG میں ایکسپورٹ کریں۔ لاس لیس فارمیٹ متن کو تیز رکھتا ہے، جو فائل سائز سے زیادہ اہمیت رکھتا ہے جب اسکرین شاٹ پڑھنے کے لیے ہو۔</p>\n<h2 id=\"text-over-photos\">تصاویر پر متن: کنٹراسٹ ہی کلید ہے</h2>\n<p>تصویر پر متن کو حروف اور پس منظر کے درمیان کنٹراسٹ چاہیے ہوتا ہے۔ سفید متن والی روشن تصویر ناکام ہوتی ہے، اور سیاہ متن والی تاریک تصویر بھی اتنی ہی بری طرح ناکام ہوتی ہے۔</p>\n<p>سفید حروف کو پڑھنے کے قابل بنانے کے لیے متن کے پیچھے تصویر کو گہرا کریں۔ پوری تصویر پر 20 سے 30 فیصد چمک کمی متن کے لیے تاریک علاقہ بنا دیتی ہے۔</p>\n<p>متبادل طور پر، روشن اور تاریک علاقوں کو الگ کرنے کے لیے تصویر کا کنٹراسٹ بڑھائیں۔ زیادہ کنٹراسٹ والا پس منظر متن کو بیٹھنے کے لیے صاف سطح دیتا ہے۔</p>\n<p>پڑھنے کے قابل متن کی مکمل گائیڈ کے لیے <a href=\"/ur/blog/contrast-readability-tasveer-par-text/\">Contrast for Readability: Text Over Photos</a> پڑھیں۔</p>\n<h2 id=\"common-confusions\">تینوں کے درمیان عام الجھنیں</h2>\n<p>سب سے عام الجھن چمک اور کنٹراسٹ کو ایک ہی چیز سمجھنا ہے۔ وہ نہیں ہیں: چمک سطح کو منتقل کرتی ہے، جبکہ کنٹراسٹ پھیلاؤ کو بدلتا ہے، اور دونوں مختلف مسائل حل کرتے ہیں۔</p>\n<p>دوسری الجھن چپٹی تصویر کو ٹھیک کرنے کے لیے چمک استعمال کرنا ہے۔ چپٹی تصویر پہلے سے درست سطح پر ہوتی ہے، اس لیے اسے روشن کرنا صرف اسے روشن اور چپٹا بناتا ہے، گہرا نہیں۔</p>\n<p>لوگ تاریک تصویر کو ٹھیک کرنے کے لیے کنٹراسٹ بھی استعمال کرتے ہیں۔ زیادہ کنٹراسٹ والی تاریک تصویر پھر بھی تاریک ہوتی ہے، بس گہرے سایوں کے ساتھ، اور موضوع چھپا رہتا ہے۔</p>\n<p>حل یہ ہے کہ ایڈٹ کرنے سے پہلے تشخیص کریں۔ پوچھیں کہ کیا تصویر بہت تاریک ہے، بہت چپٹی ہے، یا دونوں، اور وہ کنٹرول چنیں جو تشخیص سے میل کھائے۔</p>\n<h2 id=\"testing-combinations\">عزم سے پہلے ترکیب آزمانا</h2>\n<p>چمک اور کنٹراسٹ کو چھوٹے قدموں میں ساتھ آزمائیں۔ تاریک، چپٹی تصویر کے لیے 10 فیصد چمک اٹھاؤ اور 10 فیصد کنٹراسٹ اضافہ اچھا نقطہ آغاز ہے۔</p>\n<p>ہر تبدیلی کے بعد موازنہ منظر استعمال کریں۔ تقسیم شدہ منظر بالکل دکھاتا ہے کہ ہر ایڈجسٹمنٹ نے کیا کیا، تاکہ آپ رک سکیں جب تصویر درست لگے۔</p>\n<p>جھلکیوں اور سایوں کو الگ الگ چیک کریں۔ جھلکیاں چمک کے تحت پہلے کٹتی ہیں، اور سائے کنٹراسٹ کے تحت پہلے کچلتے ہیں، اس لیے دونوں انتہاؤں کو جانچ چاہیے ہوتی ہے۔</p>\n<p>جب ترکیب اصل سے بدتر لگے تو ری سیٹ کریں اور دوبارہ شروع کریں۔ چھوٹے قدموں سے تازہ کوشش اکثر بہت زیادہ ایڈٹ شدہ تصویر کو بچانے کی کوشش سے بہتر ہوتی ہے۔</p>\n<h2 id=\"cheat-sheet\">فوری فیصلہ چیٹ شیٹ</h2>\n<p>چمک تب استعمال کریں جب پوری تصویر بہت تاریک یا بہت روشن ہو۔ یہ مجموعی سطح مسئلے کا تیز ترین حل ہے، اور اسکرین شاٹس اور دستاویزات کے لیے بہترین موزوں ہے۔</p>\n<p>ایکسپوزر تب استعمال کریں جب جھلکیاں اہمیت رکھتی ہوں اور آپ کا ایڈیٹر اسے دے۔ یہ چمک سے بہتر روشن علاقوں میں تفصیل محفوظ رکھتا ہے، جو لینڈ اسکیپ اور پورٹریٹ کے لیے موزوں ہے۔</p>\n<p>کنٹراسٹ تب استعمال کریں جب تصویر چپٹی اور سرمئی لگے، حالانکہ اس کی چمک درست ہو۔ چھوٹا اضافہ جان بڑھاتا ہے، جبکہ چھوٹی کمی سخت تصویر کو نرم کرتی ہے۔</p>\n<p>جب تصویر کو دونوں چاہیے ہوں تو پہلے چمک، پھر کنٹراسٹ استعمال کریں۔ ترتیب اہمیت رکھتی ہے، کیونکہ چمک سطح طے کرتی ہے اور کنٹراسٹ اس کے ارد گرد پھیلاؤ کو بہتر کرتا ہے۔</p>\n<h2 id=\"three-controls-for-thumbnails\">تھمب نیل کے لیے چمک، ایکسپوزر، اور کنٹراسٹ</h2>\n<p>ویڈیو تھمب نیل چھوٹے دکھائے جاتے ہیں، اس لیے انہیں مضبوط سطح اور صاف کنٹراسٹ چاہیے ہوتا ہے۔ تاریک، چپٹا تھمب نیل فیڈ میں غائب ہو جاتا ہے، جبکہ روشن، جان دار تھمب نیل توجہ کھینچتا ہے۔</p>\n<p>تھمب نیل کو پوری تصویر سے کچھ زیادہ روشن کریں۔ چھوٹا سائز باریکی چھپاتا ہے، اس لیے صاف، اچھی روشن تصویر موڈی تصویر سے بہتر کام کرتی ہے۔</p>\n<p>موضوع کو پس منظر سے الگ کرنے کے لیے کنٹراسٹ شامل کریں۔ صاف موضوع اور الگ پس منظر والا تھمب نیل چھوٹے سائز پر بھی فوراً پڑھا جاتا ہے۔</p>\n<p>شائع کرنے سے پہلے تھمب نیل کو اس کے حقیقی سائز پر آزمائیں۔ اسے اپنے فون پر چھوٹا کریں اور چیک کریں کہ کیا موضوع پھر بھی صاف ہے اور متن، اگر کوئی ہو، پھر بھی پڑھنے کے قابل ہے۔</p>\n<p>عملی مراحل کے لیے <a href=\"/ur/blog/tasveer-ki-brightness-kaise-badlein/\">How to Adjust Image Brightness</a> اور <a href=\"/ur/blog/tasveer-ka-contrast-kaise-badlein/\">How to Adjust Image Contrast</a> دیکھیں۔ مکمل گائیڈ کے لیے <a href=\"/ur/blog/tasveer-brightness-editor-rehnumai/\">Image Brightness Editor: Complete Guide</a> اور <a href=\"/ur/blog/tasveer-contrast-editor-rehnumai/\">Image Contrast Editor: Complete Guide</a> پڑھیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"چمک اور کنٹراسٹ میں کیا فرق ہے؟","answer":"چمک ہر پکسل کو سفید یا سیاہ کی طرف یکساں منتقل کرتی ہے، پوری ٹونل حد کو اوپر یا نیچے لے جاتی ہے۔ کنٹراسٹ سب سے تاریک اور سب سے روشن حصوں کے درمیان خلا کو پھیلاتا یا سکیڑتا ہے۔ تاریک تصویر کو چمک چاہیے ہوتی ہے، چپٹی تصویر کو کنٹراسٹ چاہیے ہوتا ہے۔"},{"question":"کیا ایکسپوزر چمک جیسا ہی ہے؟","answer":"نہیں، حالانکہ وہ ایک جیسے محسوس ہوتے ہیں۔ ایکسپوزر جھلکیوں اور سایوں کو مختلف متاثر کرتا ہے، انتہاؤں پر زیادہ تفصیل محفوظ رکھتا ہے، جبکہ چمک سب کچھ یکساں منتقل کرتی ہے۔ ایکسپوزر روشن علاقوں پر نرم ہوتا ہے۔"},{"question":"کیا میں پہلے چمک ایڈجسٹ کروں یا کنٹراسٹ؟","answer":"پہلے چمک، پھر کنٹراسٹ۔ چمک مجموعی سطح طے کرتی ہے، اور کنٹراسٹ اس سطح کے ارد گرد پھیلاؤ کو بہتر کرتا ہے۔ کنٹراسٹ تبدیلی کے بعد چمک دوبارہ چیک کریں، کیونکہ تصویر گہری یا ہلکی محسوس ہو سکتی ہے۔"},{"question":"میری تصویر روشن کرنے کے بعد چپٹی کیوں لگتی ہے؟","answer":"روشن کرنے سے سائے اٹھتے ہیں اور تاریک اور روشن کے درمیان خلا کم ہو جاتا ہے، جو تصویر کو چپٹا کرتا ہے۔ بعد میں چھوٹا کنٹراسٹ اضافہ کر کے گہرائی بحال کریں۔ 10 فیصد چمک اٹھاؤ اور 10 فیصد کنٹراسٹ اضافہ اچھا نقطہ آغاز ہے۔"},{"question":"کیا کنٹراسٹ بہت تاریک تصویر کو ٹھیک کر سکتا ہے؟","answer":"نہیں۔ کنٹراسٹ پھیلاؤ بدلتا ہے، سطح نہیں، اس لیے زیادہ کنٹراسٹ والی تاریک تصویر پھر بھی تاریک ہوتی ہے، بس گہرے سایوں کے ساتھ۔ پہلے تصویر روشن کر کے سطح ٹھیک کریں، پھر اگر وہ چپٹی لگے تو کنٹراسٹ شامل کریں۔"},{"question":"دھندلی لینڈ اسکیپ تصویر کے لیے کون سا کنٹرول استعمال کروں؟","answer":"کنٹراسٹ، عام طور پر پہلے چھوٹی چمک اٹھاؤ کے ساتھ۔ دھند ٹونل حد کو چپٹا کر دیتی ہے، اس لیے کنٹراسٹ اضافہ گہرائی بحال کرتا ہے۔ اگر تصویر تاریک ہو تو 10 فیصد چمک سے شروع کریں، پھر 10 سے 20 فیصد کنٹراسٹ شامل کریں۔"}];
